insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('SG:truck-driver','2026-08-11',0,0,0,0,15,0,0,0,2,17,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 8332 separates heavy truck and lorry driving into lorry, trailer-truck, concrete-mix, waste-truck and other heavy-truck occupations; no fake single five-digit code is used.','entry_level_basis','Practical driving entry is accessible, but the driver must hold the Singapore driving-licence class appropriate to the heavy vehicle.','qualification_note','Traffic Police Class 4 covers load-carrying vehicles above the stated unladen-weight threshold; Class 5 covers specified heavier non-load vehicles.','market_scope','No exact shortage, vacancy, salary or growth series is scored in foundation.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:logistics-coordinator','2026-08-11',0,0,0,0,15,0,0,0,5,20,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','Singapore has no single five-digit Logistics Coordinator title. Planning-heavy work aligns with 33461 Logistics/Production planner while shipment-documentation coordination overlaps 43231 Shipping clerk and 43239 Transport clerk n.e.c.','entry_level_basis','Three approved supply-chain/maritime programmes are related pathways; operations experience can also provide entry.','qualification_note','No universal personal occupational licence is identified.','market_scope','Reference codes are not aggregated into fabricated market metrics.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:aircraft-maintenance-technician','2026-08-11',0,0,0,0,12,0,0,0,1,13,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','The canonical technician spans SSOC 31211 Aeronautical engineering technician and 72320 Aircraft engine mechanic/repairer rather than one exact code.','entry_level_basis','Technical and work-study routes are relevant; two approved degree programmes are related rather than licence-conferring pathways.','qualification_note','CAAS states that an Aircraft Maintenance (Personnel) Licence is required to perform, supervise or certify maintenance work on a Singapore-registered aircraft of the applicable type; SAR-66 examination, experience and rating requirements apply.','market_scope','Licensing is not converted into demand evidence.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:commercial-pilot','2026-08-11',0,0,0,0,8,0,0,0,1,9,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC separates 21721 Commercial airline pilot from 21722 Aircraft pilot excluding commercial airline and air force; the broader CampCareer Commercial Pilot role therefore has no single primary code.','entry_level_basis','Entry requires approved flight training, theoretical examinations, flight tests, flying experience and Class 1 medical fitness.','qualification_note','CAAS requires a CPL for specified commercial public-transport/aerial-work operations, with ATPL or MPL requirements applying to other commercial flight capacities.','market_scope','No market component is inferred from licence scarcity or airline activity.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:marine-engineer','2026-08-11',0,0,0,0,10,0,0,0,1,11,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 31510 Marine engineering officer directly matches the seagoing operational engineering-officer scope; 21711 Chief/Second engineer is retained as senior progression.','entry_level_basis','Marine-engineering study plus required sea service and competency assessment form the seagoing pathway. One approved programme is direct educational preparation.','qualification_note','MPA requires valid STCW-compliant Certificate of Competency or endorsement for seafarers serving in officer capacities.','market_scope','No shortage, salary or vacancy points are assigned at foundation stage.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:deck-officer','2026-08-11',0,0,0,0,10,0,0,0,1,11,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 31521 Ship''s deck navigating officer directly covers navigating officers; 21713 Ship captain/Chief mate is retained as senior progression and harbour pilot 31522 stays separate.','entry_level_basis','Nautical training, sea service, STCW courses and competency assessment are central. The approved Maritime Studies programme is related rather than a CoC-conferring pathway.','qualification_note','MPA requires valid STCW-compliant Certificate of Competency or endorsement for officers serving onboard ships.','market_scope','Certification is not converted into labour-demand points.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:warehouse-manager','2026-08-11',0,0,0,0,10,0,0,0,4,14,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 13241 Supply and distribution/Logistics/Warehousing manager directly covers warehouse management.','entry_level_basis','Warehouse managers normally progress through logistics operations and supervisory responsibility; two approved supply-chain programmes are related pathways.','qualification_note','No universal personal occupational licence is identified; premises, dangerous-goods, forklift and workplace-safety duties remain separate controls.','market_scope','No exact 13241 market series is scored yet.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:automotive-service-technician','2026-08-11',0,0,0,0,15,0,0,0,5,20,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 72310 Automotive mechanic directly matches the canonical vehicle-service and repair scope.','entry_level_basis','Applied automotive technical training and supervised workshop experience are practical routes; no approved Singapore programme mapping is currently present.','qualification_note','No universal personal statutory occupational licence is identified for Automotive Mechanics; workshop, inspection and specialist activity requirements are separate.','market_scope','No labour-market component is inferred from vehicle regulation.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11')
